#|| Black-Scholes prices and implied volatilities for arrays of quotes.
#|| The normal CDF is W. J. Cody's rational Chebyshev approximation (Math.
#|| Comp. 23, 1969; the form R's pnorm uses), accurate in relative terms in
#|| both tails, so deep out-of-the-money prices keep their digits. Implied
#|| volatility is a safeguarded Newton iteration on log(price), from the
#|| out-of-the-money side of put-call parity, inside a bracket that falls
#|| back to bisection.

SQRT2PI_INV = 0.398942280401432677939946059934

#| The standard normal density.
def norm_pdf(x: Num) -> Num {
    return SQRT2PI_INV * exp(-0.5 * x * x)
}

# exp(-y^2 / 2) with y split as ys + (y - ys), ys a multiple of 1/16, so the
# exponent of the larger part is exact (Cody's device against cancellation)
def _gauss_tail(y: Num) -> Num {
    ys = floor(y * 16.0) / 16.0
    del = (y - ys) * (y + ys)
    return exp(-ys * ys * 0.5) * exp(-del * 0.5)
}

#| The standard normal CDF, Cody's algorithm: three rational approximations,
#| |x| < 0.674, |x| < sqrt(32), and the asymptotic tail.
def norm_cdf(x: Num) -> Num {
    y = abs(x)
    if y <= 0.67448975 {
        xsq = x * x
        xnum = 0.065682337918207449113 * xsq
        xden = xsq
        xnum = (xnum + 2.2352520354606839287) * xsq
        xden = (xden + 47.20258190468824187) * xsq
        xnum = (xnum + 161.02823106855587881) * xsq
        xden = (xden + 976.09855173777669322) * xsq
        xnum = (xnum + 1067.6894854603709582) * xsq
        xden = (xden + 10260.932208618978205) * xsq
        return 0.5 + x * (xnum + 18154.981253343561249) / (xden + 45507.789335026729956)
    }
    tail = 0.0
    if y <= 5.656854249492380195 {
        xnum = 1.0765576773720192317e-8 * y
        xden = y
        xnum = (xnum + 0.39894151208813466764) * y
        xden = (xden + 22.266688044328115691) * y
        xnum = (xnum + 8.8831497943883759412) * y
        xden = (xden + 235.38790178262499861) * y
        xnum = (xnum + 93.506656132177855979) * y
        xden = (xden + 1519.377599407554805) * y
        xnum = (xnum + 597.27027639480026226) * y
        xden = (xden + 6485.558298266760755) * y
        xnum = (xnum + 2494.5375852903726711) * y
        xden = (xden + 18615.571640885098091) * y
        xnum = (xnum + 6848.1904505362823326) * y
        xden = (xden + 34900.952721145977266) * y
        xnum = (xnum + 11602.651437647350124) * y
        xden = (xden + 38912.003286093271411) * y
        tail = _gauss_tail(y) * (xnum + 9842.7148383839780218) / (xden + 19685.429676859990727)
    }
    else {
        xsq = 1.0 / (x * x)
        xnum = 0.02307344176494017303 * xsq
        xden = xsq
        xnum = (xnum + 0.21589853405795699) * xsq
        xden = (xden + 1.28426009614491121) * xsq
        xnum = (xnum + 0.1274011611602473639) * xsq
        xden = (xden + 0.468238212480865118) * xsq
        xnum = (xnum + 0.022235277870649807) * xsq
        xden = (xden + 0.0659881378689285515) * xsq
        xnum = (xnum + 0.001421619193227893466) * xsq
        xden = (xden + 0.00378239633202758244) * xsq
        t = xsq * (xnum + 2.9112874951168792e-5) / (xden + 7.29751555083966205e-5)
        tail = _gauss_tail(y) * (SQRT2PI_INV - t) / y
    }
    if x > 0.0 {
        return 1.0 - tail
    }
    return tail
}

# The undiscounted out-of-the-money option on forward F with s = sigma sqrt(T):
# a call when K >= F, a put otherwise. Each term is a tail probability, so
# nothing large is subtracted to make something small.
def _otm(F: Num, K: Num, s: Num) -> Num {
    if s <= 0.0 {
        return 0.0
    }
    d1 = log(F / K) / s + 0.5 * s
    d2 = d1 - s
    if K >= F {
        return F * norm_cdf(d1) - K * norm_cdf(d2)
    }
    return K * norm_cdf(-d2) - F * norm_cdf(-d1)
}

#| The Black-Scholes price of a European option on a stock with continuous
#| dividend yield q. An in-the-money option is priced as the out-of-the-money
#| one plus the discounted forward intrinsic value (put-call parity).
def bs_price(S: Num, K: Num, T: Num, r: Num, q: Num, sigma: Num, is_call: Bool) -> Num {
    F = S * exp((r - q) * T)
    df = exp(-r * T)
    o = df * _otm(F, K, sigma * sqrt(T))
    if is_call and K < F {
        return o + df * (F - K)
    }
    if not is_call and K > F {
        return o + df * (K - F)
    }
    return o
}

#| bs_price over arrays of quotes (S, K, T, sigma, is_call of one length;
#| is_call is 1 for a call, 0 for a put).
def bs_prices(S: Arr, K: Arr, T: Arr, r: Num, q: Num, sigma: Arr, is_call: Arr) -> Arr {
    n = len(S)
    out = zeros(n)
    for i to n {
        out[i] = bs_price(S[i], K[i], T[i], r, q, sigma[i], is_call[i] > 0.5)
    }
    return out
}

#| The implied volatility of one quote, or NaN when the price is outside the
#| no-arbitrage bounds. Newton steps on log(otm(s)) - log(target) in
#| s = sigma sqrt(T), kept inside a bracket [lo, hi] that every evaluation
#| shrinks; a step that leaves it is replaced by bisection (or doubling while
#| hi is unknown). Stops when a step is below 4e-16 of s.
def implied_vol(price: Num, S: Num, K: Num, T: Num, r: Num, q: Num, is_call: Bool) -> Num {
    F = S * exp((r - q) * T)
    df = exp(-r * T)
    o = price / df
    if is_call and K < F {
        o = o - (F - K)
    }
    if not is_call and K > F {
        o = o - (K - F)
    }
    bound = F if K >= F else K
    if not (o > 0.0) or o >= bound {
        return 0.0 / 0.0
    }
    target = log(o)
    lo = 0.0
    hi = 1.0e300
    s = sqrt(2.0 * abs(log(F / K)))
    if s < 0.1 {
        s = 0.1
    }
    for it to 200 {
        v = _otm(F, K, s)
        sn = 0.0
        if v > 0.0 {
            f = log(v) - target
            if f == 0.0 {
                return s / sqrt(T)
            }
            if f > 0.0 {
                hi = s
            }
            else {
                lo = s
            }
            d1 = log(F / K) / s + 0.5 * s
            dv = F * norm_pdf(d1)
            sn = s - f * v / dv
        }
        else {
            lo = s
            sn = -1.0
        }
        if not (sn > lo and sn < hi) {
            sn = 0.5 * (lo + hi) if hi < 1.0e299 else 2.0 * s
        }
        if abs(sn - s) <= 4.0e-16 * s {
            return sn / sqrt(T)
        }
        s = sn
    }
    return s / sqrt(T)
}

#| implied_vol over arrays of quotes.
def implied_vols(price: Arr, S: Arr, K: Arr, T: Arr, r: Num, q: Num, is_call: Arr) -> Arr {
    n = len(price)
    out = zeros(n)
    for i to n {
        out[i] = implied_vol(price[i], S[i], K[i], T[i], r, q, is_call[i] > 0.5)
    }
    return out
}

test "Hull's example: S=42, K=40, r=10%, sigma=20%, T=0.5 (call 4.76, put 0.81)" {
    assert_near(bs_price(42.0, 40.0, 0.5, 0.1, 0.0, 0.2, true), 4.7594, 5.0e-5)
    assert_near(bs_price(42.0, 40.0, 0.5, 0.1, 0.0, 0.2, false), 0.8086, 5.0e-5)
}

test "the CDF's tails and symmetry" {
    assert_near(norm_cdf(0.0), 0.5, 0.0)
    assert_near(norm_cdf(-10.0) / 7.619853024160527e-24, 1.0, 1.0e-14)
    assert_near(norm_cdf(1.0) + norm_cdf(-1.0), 1.0, 2.0e-16)
}

test "put-call parity and the implied volatility round trip" {
    c = bs_price(100.0, 120.0, 0.25, 0.03, 0.01, 0.3, true)
    p = bs_price(100.0, 120.0, 0.25, 0.03, 0.01, 0.3, false)
    assert_near(c - p, 100.0 * exp(-0.01 * 0.25) - 120.0 * exp(-0.03 * 0.25), 1.0e-12)
    assert_near(implied_vol(c, 100.0, 120.0, 0.25, 0.03, 0.01, true) / 0.3, 1.0, 1.0e-13)
    assert_near(implied_vol(p, 100.0, 120.0, 0.25, 0.03, 0.01, false) / 0.3, 1.0, 1.0e-13)
    deep = bs_price(100.0, 300.0, 0.1, 0.0, 0.0, 0.25, true)
    assert_near(implied_vol(deep, 100.0, 300.0, 0.1, 0.0, 0.0, true) / 0.25, 1.0, 1.0e-12)
}

